<template>
    <DebugDisplay :debug="debug"></DebugDisplay>

    <div v-if="permissionsloaded" class="mt-0 w-full" role="navigation">
        <TabGroup :defaultIndex="1">
            <TabList class="flex justify-start space-x-1 bg-base-100 p-1 border border-base-300 rounded-b-md w-full shadow-sm focus:outline-none">
                <Tab v-for="tab in filteredtabs" v-slot="{ selected }">
                    <a
                        :id="tab.id"
                        class="tab px-4 py-2 text-sm font-medium transition-all duration-200 focus:outline-none flex items-center cursor-pointer"
                        :class="{
                            'text-university-blue border-b-2 border-university-blue': selected,
                            'text-brand-dark-purple/80 hover:bg-brand-light-purple/10 hover:text-brand-dark-purple': !selected,
                        }"
                    >
                        <component :is="tab.icon" :size="16" class="mr-1" /> {{ tab.label }}
                    </a>
                </Tab>
            </TabList>
            <TabPanels >
                <TabPanel v-for="tab in filteredtabs" role="main">
                    <component :is="tab.component" />
                </TabPanel>
            </TabPanels>
        </TabGroup>
    </div>
</template>

<script setup lang="ts">
    import { computed, onMounted, ref } from 'vue';
    import { storeToRefs } from 'pinia';
    import { useMstrings } from '@/stores/mstrings.js';
    import { moodleFetch } from '@/js/moodlefetch';
    import DebugDisplay from '@/components/Common/DebugDisplay.vue';
    import { TabGroup, TabList, Tab, TabPanels, TabPanel } from '@headlessui/vue';
    import { MonitorCog, Camera, Calculator, Shield, Settings2, Table } from '@lucide/vue';

    import ConfigPage from '@/views/ConfigPage.vue';
    import CaptureTable from '@/views/CaptureTable.vue';
    import AggregationTable from '@/views/AggregationTable.vue';
    import ConversionPage from '@/views/ConversionPage.vue';
    import SettingsPage from '@/views/SettingsPage.vue';
    import AuditPage from '@/views/AuditPage.vue';

    const debug = ref({});
    const haschangesettings = ref(false);
    const permissionsloaded = ref(false);
    const mstringstore = useMstrings();
    const { mstrings } = storeToRefs( mstringstore );

    const tabs = ref([
        {
            label: mstrings.value.configure ?? 'Assessment configuration',
            component: ConfigPage,
            icon: MonitorCog,
            id: 'configpage',
        },
        {
            label: mstrings.value.assessmentgradecapture ?? 'Assessment grade capture',
            component: CaptureTable,
            icon: Camera,
            id: 'capturetable',
        },
        {
            label: mstrings.value.manageconversion ?? 'Manage conversion maps',
            component: ConversionPage,
            icon: Table,
            id: 'conversionpage',
        },
        {
            label: mstrings.value.coursegradeaggregation ?? 'Course grade aggregation',
            component: AggregationTable,
            icon: Calculator,
            id: 'aggregationtable',
        },
        {
            label: mstrings.value.auditlog ?? 'Audit log',
            component: AuditPage,
            icon: Shield,
            id: 'auditpage',
        },
        {
            label: mstrings.value.settings ?? 'Settings',
            component: SettingsPage,
            icon: Settings2,
            id: 'settingspage',
        },
    ]);

    const filteredtabs = computed(() => {
        return tabs.value.filter((tab) => {
            if (tab.id == 'settingspage') {
                return haschangesettings.value;
            }
            return true;
        });
    });

    onMounted(() => {
        moodleFetch(
            'local_gugrades_has_capability',
            {
                capability: 'local/gugrades:changesettings',
            }
        )
        .then((result: any) => {
            haschangesettings.value = !!result.hascapability;
            permissionsloaded.value = true;
        })
        .catch((error) => {
            console.error(error);
            debug.value = error;
            permissionsloaded.value = true;
        });
    });

</script>
